# Substring of a service name -> slug. Names arrive from limits.json and from the
# web-access cards, already decorated by the instance ("Apify (main profile)",
# "Codex (week)", "Brave Free"), so matching is by containment, not equality.
MATCH: tuple[tuple[str, str], ...] = (
    ("tavily", "tavily"),
    ("elevenlabs", "elevenlabs"),
    ("browserbase", "browserbase"),
    ("firecrawl", "firecrawl"),
    ("apify", "apify"),
    ("brave", "brave"),
    ("codex", "openai"),
    ("openai", "openai"),
    ("gpt", "openai"),
)


def icon_slug(name: str) -> str:
    """Slug of the mark for a service name, or "" when there is none."""
    n = str(name or "").lower()
    for needle, slug in MATCH:
        if needle in n:
            return slug
    return ""


def brand_icon(name: str, cls: str = "bi") -> str:
    """Inline monochrome mark for a service name; empty string when unknown."""
    slug = icon_slug(name)
    if not slug:
        return ""
    vb, ds = ICONS[slug]
    body = "".join(f'<path d="{d}"/>' for d in ds)
    return f'<svg class="{cls}" viewBox="{vb}" fill="currentColor" aria-hidden="true">{body}</svg>'
